<template>
 <view :class="['album-page ui-v2',petThemeClass,memorial?'memory-album':'']" :style="[appThemeStyle,insets]">
  <view class="album-nav"><button class="nav-icon" :aria-label="tr('back')" @click="back"><uni-icons type="left" size="21" color="#BCC4AE"/></button><text>{{petName}}</text><button class="nav-icon" :aria-label="v('bookOptions')" @click="bookMenu"><uni-icons type="more-filled" size="22" color="#BCC4AE"/></button></view>
  <scroll-view class="album-scroll" scroll-y :scroll-top="scrollTop" :scroll-into-view="scrollTarget" @scroll="scrollTop=$event.detail.scrollTop"><view class="book-body">
   <view class="book-heading"><view class="book-heading-copy"><text class="heading">{{tr(memorial?'memoryAlbum':'lifeAlbum')}}</text><text class="book-subtitle">{{memorial?'那些熟悉的片段，可以慢慢读。':'一起过的日子，都有迹可循。'}}</text></view><button v-if="!recordReadError" class="new-page" :aria-label="memorial?'写一封信':'记录一刻'" @click="edit()"><uni-icons :type="memorial?'compose':'plusempty'" size="22" color="#FFFDF8"/></button></view>
   <view v-if="recordReadError" class="record-read-error" :style="{'--ui-font-scale':uiFontScale}" role="alert"><text class="read-error-title">资料暂时没能读取</text><text>为保护已有内容，暂不开放编辑。请重试读取。</text><button @click="load">重新读取</button></view>
   <template v-else>
   <AppSegmented v-model="viewMode" :options="[{value:'records',label:memorial?'回忆':'记录'},{value:'photos',label:'照片'},{value:'works',label:'作品'}]"/>
   <view class="reading-toolbar"><text class="reading-count">{{viewMode==='works'?workResult.total+' 件已保存作品':resultCount ? resultCount+(viewMode==='photos'?' 段含照片记录':' 段'+(memorial?'记忆':'日常')) : '等一个值得留下的片段'}}</text><button class="toolbar-action" :class="{active:findOpen||query}" :aria-expanded="findOpen" :aria-label="viewMode==='works'?'查找作品':'查找记录'" @click="findOpen=!findOpen"><uni-icons type="search" size="18" color="currentColor"/><text>查找</text></button><button v-if="viewMode!=='works'" class="toolbar-action" :class="{active:searchOpen||hasFilters}" :aria-expanded="searchOpen" @click="searchOpen=!searchOpen">筛选<text v-if="hasFilters" class="filter-dot">·</text></button><button class="toolbar-action" :class="{active:toolsOpen}" :aria-expanded="toolsOpen" @click="toolsOpen=!toolsOpen">整理</button></view>
   <view v-if="directory.length && viewMode!=='works' && filter!=='drafts'" class="period-browser">
    <button class="period-toggle" :aria-expanded="directoryOpen" @click="directoryOpen=!directoryOpen"><view><text class="period-title">{{periodLabel}}</text><text class="period-caption">{{memorial?'按记得的时间，慢慢翻阅':directory.length+' 个时间章节 · '+directory.reduce((n,g)=>n+g.count,0)+' 段日常'}}</text></view><uni-icons :type="directoryOpen?'top':'bottom'" size="16" color="currentColor"/></button>
    <view v-if="directoryOpen" class="period-list"><button :class="{selected:!period}" @click="choosePeriod('')"><text>全部片段</text><text>{{directory.reduce((n,g)=>n+g.count,0)}} 段</text></button><button v-for="group in directory" :key="group.key" :class="{selected:period===group.key}" @click="choosePeriod(group.key)"><text>{{group.label}}</text><text>{{group.count}} 段{{group.photos?' · '+group.photos+' 张照片':''}}</text></button></view>
    <button v-if="period && !directoryOpen" class="period-clear" @click="choosePeriod('')">查看全部时间</button>
   </view>
   <view v-if="findOpen || query" class="find-records"><uni-icons type="search" size="18" color="#BCC4AE"/><input v-model="query" :placeholder="viewMode==='works'?'查找作品标题或已保存文字':'查找文字、标签或照片说明'" confirm-type="search"/><button v-if="query" aria-label="清除查找" @click="query=''">清除</button></view>
   <view v-if="searchOpen && viewMode!=='works'" class="record-filters"><view class="filter-top"><button @click="filterMenu">{{filter==='all'?v('allContent'):tr(filter)}} <uni-icons type="bottom" size="12" color="currentColor"/></button><button v-if="draftCount" class="draft-entry" @click="filter=filter==='drafts'?'all':'drafts'">{{v('draftCount')}} · {{draftCount}}</button></view><view class="filter-fields"><picker mode="date" fields="month" @change="month=$event.detail.value"><button>{{month||'跳到月份'}}</button></picker><picker mode="date" @change="from=$event.detail.value"><button>{{from||'起始日期'}}</button></picker><picker mode="date" @change="to=$event.detail.value"><button>{{to||'结束日期'}}</button></picker><input v-model="tag" placeholder="明确标签"/><picker :range="['生活文字','照护观察']" @change="searchType=$event.detail.value==='1'?'care':'life'"><button>{{searchType==='care'?'照护观察':'生活文字'}}</button></picker><button @click="onlyFavorites=!onlyFavorites">{{onlyFavorites?'仅收藏 ✓':'仅收藏'}}</button></view><button class="clear-filters" @click="resetSearch">清除筛选</button><text v-if="from||to">日期区间仅匹配准确日期；时间未详的记录可按月份或关键词查找。</text></view>
   <view v-if="toolsOpen" class="organize-panel"><text class="tools-title">{{memorial?'按自己的节奏翻阅':'把日常整理成喜欢的样子'}}</text><view class="recipe-actions"><button class="backfill" @click="backfill">补记一刻</button><button v-if="rows.length" class="backfill" @click="manualBooklet">整理几页</button><button @click="viewMode='photos'">挑选照片做对照</button><button v-if="draftCount" @click="viewMode='records';filter='drafts';toolsOpen=false">继续草稿 · {{draftCount}}</button></view><view class="recall-actions"><button @click="browseRecall">翻翻以前</button><button v-if="!memorial" @click="toggleRecall">{{recallEnabled?'关闭主动回看':'允许在册里主动回看'}}</button></view><button v-if="!memorial && (recipes.length||atlas.length||savedProposals.length)" class="collection-disclosure" @click="toggleChapters">{{tr('collections')}} · {{tr('atlas')}} <uni-icons :type="extras?'top':'bottom'" size="15" color="currentColor"/></button></view>
   <view v-if="comparison.length" class="comparison-bar"><text>已选 {{comparison.length}} / 2 张照片</text><button v-if="comparison.length===2" @click="makeComparison">预览两图对照</button><button @click="comparison=[]">取消选择</button></view>
   <button v-if="viewMode==='photos' && photoRows.length && !photoExportSelecting" class="photo-export-entry" @click="beginPhotoExport">选择照片保存</button>
   <view v-if="photoExportSelecting" class="photo-export-panel" role="region" aria-label="保存生活照片">
    <text class="photo-export-title">保存生活照片</text><text>已选 {{photoExportSelected.length}} / 30 张 · {{photoExportTarget}}</text>
    <text>{{photoExportTarget==='浏览器下载'?'原图打包为ZIP，单次最多64MB。请确认下载文件已保存。':'逐张保存原图到系统相册，失败时保留未完成的选择。'}}</text>
    <text>仅包含所选生活照片，不是完整资料备份。</text>
    <view class="photo-export-actions"><button :disabled="photoExportBusy" @click="selectVisibleExportPhotos">选择本页照片</button><button :disabled="photoExportBusy || !photoExportSelected.length" @click="startPhotoExport">{{photoExportBusy?'正在处理':photoExportResult?'保存未完成的照片':'保存所选照片'}}</button><button v-if="photoExportBusy" @click="photoExportCancelled=true">停止后续保存</button><button v-else @click="resetPhotoExport">结束选择</button></view>
    <text v-if="photoExportBusy" role="status">正在处理 {{photoExportProgress.index}} / {{photoExportProgress.total}} 张</text>
    <text v-if="photoExportResult" class="photo-export-result" role="status">{{photoExportResult}}</text>
    <text v-for="item in photoExportFailures" :key="item.key" class="photo-export-failure">{{item.label}}</text>
   </view>
   <view v-if="memorial && viewMode==='records'" class="memory-categories"><button :class="{selected:filter==='all'}" @click="filter='all'">全部片段</button><button :class="{selected:filter==='memory'}" @click="filter='memory'">回忆片段</button><button :class="{selected:filter==='letter'}" @click="filter='letter'">写给它的信</button></view>
   <view v-if="recall" class="recall-card"><text>{{recall.label}}</text><button @click="openRecall">查看原记录</button><button @click="hideRecall">这条不再推荐</button><button @click="pauseRecall">暂时不看</button><button @click="closeRecall">关闭回看</button></view>
   <view v-if="metadataRow" class="record-filters"><text>整理这条记录</text><input v-model="metadataTags" placeholder="生活标签，用逗号分隔"/><input v-model="metadataMilestone" placeholder="值得记住的一刻（可选，自行命名）"/><view class="recipe-actions"><button v-for="(label,key) in {habit:'小习惯',favoriteThing:'喜欢的东西',first:'我们的第一次',ordinary:'普通的一天'}" :key="key" @click="metadataTags=metadataTags?metadataTags+'，'+key:key">{{label}}</button></view><text>“第一次”仅由你确认；删除节点名称即可取消标记。</text><button @click="saveMetadata">保存整理</button><button @click="metadataRow=null">取消</button></view>
   <view v-if="!rows.length" class="empty-book"><view class="sample-page"><image v-if="exampleUrl" :src="exampleUrl" mode="widthFix"/><text class="sample-label">{{v('example')}}</text></view><text class="empty-title">{{v(memorial?'memoryEmptyTitle':'bookEmptyTitle')}}</text><text class="empty-copy">{{memorial?'这里可以收下旧照片、回忆和写给它的信。什么时候开始，都由你。':v('bookEmptyCopy')}}</text><button class="start-page" @click="edit()">{{v(memorial?'startMemory':'start')}}</button></view>
   <template v-else>
    <view id="album-record-results"></view>
    <RecordPager v-if="viewMode!=='works'" :total="resultCount" :offset="recordResult.offset" :size="pageLimit" :disabled="photoExportBusy" :style="{'--ui-font-scale':uiFontScale}" @change="changeRecordPage"/>
    <view v-if="viewMode==='works' && visibleWorks.length" class="work-section" :style="{'--ui-font-scale':uiFontScale}"><view id="album-work-results" class="section-heading"><text>{{v('recentWorks')}}</text><text>{{workResult.total}} 件</text></view><RecordPager :total="workResult.total" :offset="workResult.offset" :size="4" unit="件作品" label="作品分页" :style="{'--ui-font-scale':uiFontScale}" @change="changeWorkPage"/><scroll-view scroll-x class="work-scroll"><view class="work-track"><view v-for="row in visibleWorks" :key="row.id" class="work-cover"><button class="cover-open" @click="edit(row)"><image v-if="covers[row.id]" :src="covers[row.id]" mode="aspectFit"/><text v-else class="cover-loading">{{coverErrors[row.id]?tr('mediaError'):'…'}}</text></button><view class="work-caption"><text @click="edit(row)">{{row.title || (row._template==='day'?v('layoutDay'):row._template==='letter'?v('layoutLetter'):tr('template_'+row._template))}}</text><button :aria-label="v('more')" @click="rowMenu(row)">···</button></view></view></view></scroll-view><RecordPager :total="workResult.total" :offset="workResult.offset" :size="4" unit="件作品" label="作品分页" :style="{'--ui-font-scale':uiFontScale}" @change="changeWorkPage"/><button class="make-from-records" @click="manualBooklet">从已有记录，再整理几页</button></view>
    <view v-if="viewMode==='records' && visibleRecords.length" class="record-section"><view v-for="(row,index) in visibleRecords" :key="row.id" class="record-item"><text v-if="!index || row.monthLabel!==visibleRecords[index-1].monthLabel" class="month-heading">{{monthHeading(row)}}</text><view class="entry"><view class="entry-date"><text>{{row.eventLabel || row.dateText || row.localDate || tr('unknownDate')}}</text><button :aria-label="v('more')" @click="rowMenu(row)">···</button></view><view class="record-preview" @click="edit(row)"><image v-if="recordPhotos[row.id]" :src="recordPhotos[row.id]" mode="aspectFit"/><view class="record-copy"><text v-if="row.title" class="entry-title">{{row.title}}</text><text class="entry-text">{{recordExcerpt(row)}}</text><view class="entry-footer"><text class="entry-kind">{{row.dailyVersion?'日常记录':tr(row._group || row.kind)}}{{row.favorite?' · ♥':''}}</text><text class="entry-read">阅读原记录 <uni-icons type="right" size="12" color="currentColor"/></text></view></view></view></view></view></view>
    <view v-if="viewMode==='photos'" class="life-photo-grid"><view v-for="item in photoRows" :key="item.key" class="life-photo"><button class="photo-open" @click="openPhoto(item)"><image v-if="recordPhotos[item.key]" :src="recordPhotos[item.key]" mode="aspectFill" lazy-load @error="photoError(item.key)"/><text v-else>{{coverErrors[item.key]?'照片暂不可读取':'正在读取照片…'}}</text></button><text class="photo-date">{{item.row.eventLabel}}</text><text class="photo-caption">{{item.asset.caption||''}}</text><view class="photo-actions"><button @click="edit(item.row)">查看原记录</button><button v-if="!photoExportSelecting" :class="{selected:comparison.some(c=>c.recordId===item.row.id&&c.assetId===item.asset.id)}" @click="selectComparison(item)">{{comparison.some(c=>c.recordId===item.row.id&&c.assetId===item.asset.id)?'已选入对照':'选入对照'}}</button><button v-else :disabled="photoExportBusy" :aria-pressed="photoExportSelected.some(ref=>ref.key===item.key)" :class="{selected:photoExportSelected.some(ref=>ref.key===item.key)}" @click="toggleExportPhoto(item)">{{photoExportSelected.some(ref=>ref.key===item.key)?'已选择保存':'选择保存'}}</button></view></view></view>
    <RecordPager v-if="viewMode!=='works'" :total="resultCount" :offset="recordResult.offset" :size="pageLimit" :disabled="photoExportBusy" :style="{'--ui-font-scale':uiFontScale}" @change="changeRecordPage"/>
    <view v-if="viewMode==='photos' && !photoRows.length" class="no-matches"><text>{{query||hasFilters?'这个范围内没有生活照片。':'还没有可显示的生活照片。'}}</text><text>照护、报告和用途未知的附件仍在原记录中。</text><button v-if="query||hasFilters" @click="resetSearch">查看全部照片</button><button @click="viewMode='records'">返回记录</button></view>
    <view v-if="viewMode==='records'&&!visibleRecords.length||viewMode==='works'&&!visibleWorks.length" class="no-matches"><text>{{viewMode==='works'?(query?'没有匹配的作品':'还没有整理好的作品'):v('noMatches')}}</text><button v-if="viewMode==='works' && query" @click="query=''">查看全部作品</button><button v-else-if="viewMode==='works'" @click="manualBooklet">从已有记录整理几页</button><button v-else-if="query||hasFilters" @click="resetSearch">查看全部记录</button></view>
   </template>
   <view v-if="extras" id="album-chapters" class="book-extras"><view class="section-heading"><text>日常里的小章节</text><button @click="extras=false">收起</button></view><button v-for="recipe in recipes" :key="recipe.key" :disabled="!recipe.available" @click="openRecipe(recipe)">{{recipe.month||''}} {{tr('collection_'+recipe.rule)}}{{!recipe.available?' · '+tr('recipeMissing'):''}}</button><button v-for="p in savedProposals" :key="p.id" @click="openProposal(p)">{{tr('proposal_'+p.id)}}</button><view v-for="chapter in atlas" :key="chapter.key" class="atlas-chapter"><text>{{tr(chapter.key)}} · 你记录过的 {{chapter.sources.length}} 条</text><button v-for="source in chapter.sources" :key="source.id" @click="edit(source)">{{source.title||v('photoOnly')}}</button></view></view>
   <text v-if="message" class="status" role="status" :style="{'--ui-font-scale':uiFontScale}">{{message}}</text><button v-if="cleanupPending" class="retry-cleanup" @click="retryCleanup">{{tr('retryCleanup')}}</button><button class="local-label" @click="showLocal">{{v('local')}} <uni-icons type="info" size="13" color="currentColor"/></button>
   </template>
  </view></scroll-view><NarrativeCanvas ref="coverCanvas"/>
 </view>
</template>
<script>
import {photoExportReference,photoExportPlan} from '../../common/photo-export-core.js';
import {exportLifePhotos,photoExportDestination} from '../../common/photo-export.js';
import {recallCandidate} from '../../common/record-recall.js';
import {localEventDate} from '../../common/narrative-store.js';
import {queryRecordPage,queryWorkPage,lifeText,lifePhotos,hasCareContent,buildRecordDirectory,recordPeriodLabel} from '../../common/record-views.js';
import {subscribeAccountScope} from '../../common/auth-store.js';
import NarrativeCanvas from '../../components/NarrativeCanvas.vue';
import RecordPager from '../../components/RecordPager.vue';
import {creativeInsets} from '../../common/creative-insets.js';
import {resolveNarrativePhoto,releaseNarrativePhoto} from '../../common/narrative-media.js';
import {getActivePet,subscribePetSelection} from '../../common/pet-store.js';
import {getNarrativeStore,narrativeMode} from '../../common/narrative-store.js';
import {captureDataScope,isDataScopeCurrent} from '../../common/scoped-storage.js';
import {t} from '../../common/i18n.js';
import {syncCollections,collectionRecipes,lifeAtlas} from '../../common/companion-collection.js';
import {COMPANION_PROPOSALS} from '../../common/companion-proposals.js';
import {narrativeMediaRefs,removeUnusedNarrativeMedia} from '../../common/narrative-media.js';
export default {
 components:{NarrativeCanvas,RecordPager},
 data:()=>({removalEpoch:0,photoExportSelecting:false,photoExportSelected:[],photoExportBusy:false,photoExportCancelled:false,photoExportEpoch:0,photoExportProgress:{index:0,total:0},photoExportResult:'',photoExportFailures:[],photoExportTarget:photoExportDestination(),recordReadError:false,directoryOpen:false,period:'',findOpen:false,toolsOpen:false,recall:null,recallManual:false,recallEnabled:false,recallSnoozedUntil:'',comparison:[],metadataRow:null,metadataTags:'',metadataMilestone:'',viewMode:'records',query:'',month:'',from:'',to:'',tag:'',onlyFavorites:false,searchType:'life',searchOpen:false,pageLimit:30,recordOffset:0,workOffset:0,scrollTop:0,scrollTarget:'',contextKey:'',insets:creativeInsets(),covers:{},coverErrors:{},recordPhotos:{},exampleUrl:'',coverEpoch:0,extras:false,visible:true,petName:'',petId:'',scope:null,store:null,memorial:false,rows:[],filter:'all',filters:['all','life','memory','letter','drafts','works','favorites'],message:'',recipes:[],atlas:[],savedProposals:[],proposalsClosed:false,cleanupPending:false}),
 computed:{directory(){return buildRecordDirectory(this.rows,{namespace:this.scope?.namespace,petId:this.petId,photosOnly:this.viewMode==='photos'});},periodLabel(){return this.period?recordPeriodLabel(this.period):'按月翻阅';},hasFilters(){return !!(this.period||this.month||this.from||this.to||this.tag||this.onlyFavorites||this.searchType!=='life'||this.filter!=='all');},recordResult(){return queryRecordPage(this.shown.filter(r=>r._group!=='works'&&(this.filter==='drafts'||r._group!=='drafts')),{query:this.query,period:this.period,month:this.month,from:this.from,to:this.to,tag:this.tag,favorite:this.onlyFavorites,type:this.searchType,namespace:this.scope?.namespace,petId:this.petId,limit:this.pageLimit,offset:this.recordOffset,photosOnly:this.viewMode==='photos'});},resultCount(){return this.recordResult.total;},photoRows(){return this.visibleRecords.filter(r=>!hasCareContent(r)).flatMap(row=>lifePhotos(row).map(asset=>({key:row.id+':'+asset.id,row,asset})));},draftCount(){return this.rows.filter(r=>r._group==='drafts').length;},workResult(){return queryWorkPage(this.shown,{query:this.query,offset:this.workOffset});},visibleWorks(){return this.workResult.rows;},visibleRecords(){return this.recordResult.rows.slice(0,this.pageLimit);},shown(){return this.rows.filter(r=>this.filter==='all'||(this.filter==='favorites'?r.favorite:(r._group || r.kind)===this.filter));}},
 watch:{period(){this.searchChanged();},query(){this.searchChanged();},month(){this.searchChanged();},from(){this.searchChanged();},to(){this.searchChanged();},tag(){this.searchChanged();},onlyFavorites(){this.searchChanged();},searchType(){this.searchChanged();},viewMode(value){if(value==='works'){this.filter='works';this.searchOpen=false;}if(value!=='photos')this.resetPhotoExport();if(value!=='works'&&this.filter==='works')this.filter='all';this.searchChanged();},filter(){this.searchChanged();}},
 onLoad(){this.unsubscribe=subscribePetSelection(()=>this.load());this.unsubscribeScope=subscribeAccountScope(()=>this.load());},
 onShow(){this.visible=true;this.insets=creativeInsets();this.load();},
 onHide(){this.resetPhotoExport();this.visible=false;this.message='';this.recall=null;this.recallManual=false;this.metadataRow=null;this.clearCovers();this.rows=[];this.atlas=[];this.recipes=[];this.savedProposals=[];},
 onUnload(){this.resetPhotoExport();const key=JSON.stringify([captureDataScope(),getActivePet()?.id]);if(this.contextKey!==key){this.resetSearch();this.findOpen=false;this.searchOpen=false;this.toolsOpen=false;this.extras=false;this.scrollTarget='';this.comparison=[];this.metadataRow=null;this.recall=null;this.recallManual=false;this.viewMode='records';this.scrollTop=0;this.contextKey=key;}this.clearCovers();this.unsubscribe?.();this.unsubscribeScope?.();},
 methods:{
  resetPhotoExport(){this.photoExportEpoch++;this.photoExportCancelled=true;this.photoExportSelecting=false;this.photoExportSelected=[];this.photoExportBusy=false;this.photoExportProgress={index:0,total:0};this.photoExportResult='';this.photoExportFailures=[];},
  beginPhotoExport(){if(!this.current())return;this.resetPhotoExport();this.photoExportCancelled=false;this.photoExportSelecting=true;this.comparison=[];this.toolsOpen=false;this.searchType='life';if(['drafts','works'].includes(this.filter))this.filter='all';},
  toggleExportPhoto(item){if(!this.current()||this.photoExportBusy)return;this.photoExportResult='';this.photoExportFailures=[];const index=this.photoExportSelected.findIndex(ref=>ref.key===item.key);if(index>=0){this.photoExportSelected.splice(index,1);return;}if(this.photoExportSelected.length>=30){this.photoExportResult='本次最多选择30张，请分批保存。';return;}try{const ref=photoExportReference(item.row,item.asset);photoExportPlan(this.store.list(),[ref],this.scope,this.petId);this.photoExportSelected.push(ref);}catch(_){this.photoExportResult='原记录已变化，请重新打开照片页后选择。';}},
  selectVisibleExportPhotos(){if(!this.current()||this.photoExportBusy)return;for(const item of this.photoRows){if(this.photoExportSelected.some(ref=>ref.key===item.key))continue;if(this.photoExportSelected.length>=30){this.photoExportResult='已选满30张，其余照片可以下一批保存。';break;}this.toggleExportPhoto(item);}},
  async startPhotoExport(){
   if(!this.current()||this.photoExportBusy||!this.photoExportSelected.length)return;
   const epoch=++this.photoExportEpoch,scope=this.scope,petId=this.petId,store=this.store,selected=this.photoExportSelected.map(ref=>({...ref}));
   const current=()=>epoch===this.photoExportEpoch&&this.visible&&this.current();
   this.photoExportBusy=true;this.photoExportCancelled=false;this.photoExportResult='';this.photoExportFailures=[];this.photoExportProgress={index:0,total:selected.length};
   try{
    const items=photoExportPlan(store.list(),selected,scope,petId);
    const report=await exportLifePhotos(items,{scope,petId,isCurrent:current,cancelled:()=>this.photoExportCancelled,sourceCurrent:item=>photoExportPlan(store.list(),[item],scope,petId),progress:value=>{if(current())this.photoExportProgress=value;}});
    if(!current())return;
    const finished=new Set(report.results.filter(item=>['saved','download-started'].includes(item.status)).map(item=>item.key));
    this.photoExportSelected=selected.filter(ref=>!finished.has(ref.key));
    const remaining=this.photoExportSelected.length;
    this.photoExportResult=(report.mode==='archive'?`已发起 ${finished.size} 张原图下载，请检查浏览器下载列表。`:`已保存 ${finished.size} 张到系统相册。`)+(remaining?`还有 ${remaining} 张未完成，选择仍保留。`:'')+(report.cancelled?'已停止后续保存。':'');
    this.photoExportFailures=report.results.flatMap((item,index)=>item.status==='failed'?[{key:item.key,label:`第 ${index+1} 张：`+(item.errorCode==='PHOTO_EXPORT_SIZE_LIMIT'?'超出单次大小，请减少选择后重试。':item.errorCode==='PHOTO_EXPORT_ALBUM_FAILED'?'相册保存未能确认，请先检查相册，再决定是否重试。':'暂时未能保存，原记录仍保留。')}]:[]);
   }catch(_){if(current()){this.photoExportResult='原记录暂时无法读取或已变化，请重新选择后保存。';this.photoExportSelected=[];}}
   finally{if(current())this.photoExportBusy=false;}
  },
  choosePeriod(key){if(!this.current())return;this.resetSearch();this.period=key;if(this.viewMode!=='photos')this.viewMode='records';this.directoryOpen=false;},
  async toggleChapters(){this.extras=!this.extras;this.scrollTarget='';if(!this.extras)return;await this.$nextTick();if(this.current()&&this.extras)this.scrollTarget='album-chapters';},
  monthHeading(row){const label=row.monthLabel||'时间未详';return label.replace(/^(\d{4})-(\d{2})/,(_,year,month)=>year+'年'+Number(month)+'月');},
  updateRecall(){if(!this.current())return;const state=this.store.read().proposals;this.recallEnabled=!!state.recallEnabled;this.recallSnoozedUntil=state.recallSnoozedUntil||'';this.recall=recallCandidate(this.store.list(),{namespace:this.scope.namespace,petId:this.petId,mode:this.memorial?'deceased':'current',enabled:this.recallEnabled,manual:this.recallManual,snoozedUntil:this.recallSnoozedUntil});},
  recallSetting(patch){if(!this.current())return;this.store.updateSection('proposals',{...this.store.read().proposals,...patch});this.updateRecall();},
  browseRecall(){this.recallManual=true;this.updateRecall();if(!this.recall)this.message='暂时没有适合回看的生活片段。原记录仍可在册里查看。';},
  toggleRecall(){this.recallManual=false;this.recallSetting({recallEnabled:!this.recallEnabled,recallSnoozedUntil:''});},
  closeRecall(){this.recallManual=false;this.recallSetting({recallEnabled:false});this.message='已关闭主动回看，原记录仍保留。';},
  pauseRecall(){this.recallManual=false;this.recallSetting({recallSnoozedUntil:localEventDate()});this.recall=null;},
  hideRecall(){if(!this.current()||!this.recall)return;this.store.setMetadata(this.recall.recordId,{hidden:true});this.recall=null;this.refresh();this.message='这条不再主动推荐，仍可在册里查看。';},
  openRecall(){if(!this.current()||!this.recall)return;const selected=this.recall;this.updateRecall();if(!this.recall||this.recall.recordId!==selected.recordId){this.message='来源已更新，请重新选择。';return;}this.edit(this.store.list().find(r=>r.id===selected.recordId));},

  saveMetadata(){if(!this.current()||!this.metadataRow)return;try{this.store.setMetadata(this.metadataRow.id,{tags:[...new Set(this.metadataTags.split(/[,，]/).map(s=>s.trim()).filter(Boolean))],milestone:this.metadataMilestone.trim()});this.metadataRow=null;this.refresh();}catch(_){this.message='整理尚未保存，请重试。';}},
  manualBooklet(){if(this.current())uni.navigateTo({url:'/pages/card-compose/card-compose?booklet=manual&petId='+encodeURIComponent(this.petId)});},
  selectComparison(item){const index=this.comparison.findIndex(c=>c.recordId===item.row.id&&c.assetId===item.asset.id);if(index>=0)this.comparison.splice(index,1);else if(this.comparison.length<2)this.comparison.push({recordId:item.row.id,assetId:item.asset.id});else this.message='一次选择两张，先取消其中一张再替换。';},
  makeComparison(){if(this.current()&&this.comparison.length===2)uni.navigateTo({url:'/pages/card-compose/card-compose?petId='+encodeURIComponent(this.petId)+'&compare='+encodeURIComponent(JSON.stringify(this.comparison))});},

  resetSearch(){this.recordOffset=0;this.workOffset=0;this.period='';this.directoryOpen=false;this.query='';this.month='';this.from='';this.to='';this.tag='';this.onlyFavorites=false;this.searchType='life';this.filter='all';},
  searchChanged(){this.workOffset=0;this.recordOffset=0;this.pageLimit=30;this.scrollTarget='';this.scrollTop=0;this.loadCovers();},
  async changeWorkPage(offset){if(!this.current())return;this.workOffset=Math.max(0,Math.floor(Number(offset)||0));this.scrollTarget='';this.loadCovers();await this.$nextTick();if(this.current())this.scrollTarget='album-work-results';},
  async changeRecordPage(offset){if(!this.current()||this.photoExportBusy)return;this.recordOffset=Math.max(0,Math.floor(Number(offset)||0));this.scrollTarget='';this.loadCovers();await this.$nextTick();if(this.current())this.scrollTarget='album-record-results';},
  recordExcerpt(row){return lifeText(row)|| (hasCareContent(row)?'照护记录 · 查看原始观察':this.v('photoOnly'));},
  backfill(){if(this.current())uni.navigateTo({url:'/pages/calendar/calendar?moment=1&petId='+encodeURIComponent(this.petId)});},
  openPhoto(item){if(!this.current())return;const url=this.recordPhotos[item.key];if(url)uni.previewImage({urls:[url],current:url});else if(!this.coverErrors[item.key]){return;}else{this.message='照片暂不可读取，原记录仍保留。';this.loadCovers();}},
  photoError(key){this.recordPhotos={...this.recordPhotos,[key]:''};this.coverErrors={...this.coverErrors,[key]:true};this.message='照片暂不可读取，原记录仍保留。';},
  v(k){return t('creative.'+k);},
  showLocal(){uni.showModal({title:this.v('local'),content:this.v('localDetail'),showCancel:false});},
  async filterMenu(){const options=['all','life','memory','letter','favorites','works'];try{const result=await new Promise((success,fail)=>uni.showActionSheet({itemList:options.map(k=>k==='favorites'?this.v('onlyFavorites'):this.tr(k)),success,fail}));this.filter=options[result.tapIndex];if(this.filter==='works'){this.viewMode='works';this.loadCovers();}else this.viewMode='records';}catch(_){}},
  async bookMenu(){const actions=['local'];if(!this.memorial&&this.proposalsClosed)actions.push('restore');try{const r=await new Promise((success,fail)=>uni.showActionSheet({itemList:actions.map(a=>a==='local'?this.v('local'):this.tr('restoreProposals')),success,fail}));if(actions[r.tapIndex]==='local')this.showLocal();else this.restoreProposals();}catch(_){}},
  async rowMenu(row){const options=row._group?['delete']:['favorite','hidden','organize','delete'];try{const r=await new Promise((success,fail)=>uni.showActionSheet({itemList:options.map(k=>k==='favorite'?this.tr(row.favorite?'unfavorite':'favorite'):k==='hidden'?this.tr(row.hidden?'showAgain':'hide'):k==='organize'?'整理标签与节点':this.tr('delete')),success,fail}));const action=options[r.tapIndex];if(action==='delete')this.remove(row);else if(action==='organize'){this.metadataRow=row;this.metadataTags=(row.tags||[]).join('，');this.metadataMilestone=row.milestone||'';this.scrollTop=0;}else this.toggle(row,action);}catch(_){}},
  clearCovers(){this.coverEpoch++;Object.values(this.recordPhotos).forEach(releaseNarrativePhoto);this.recordPhotos={};this.covers={};this.coverErrors={};this.exampleUrl='';},
  async loadCovers(){this.clearCovers();const epoch=this.coverEpoch,valid=()=>epoch===this.coverEpoch&&this.current()&&this.visible;await this.$nextTick();if(!valid())return;
   if(!this.rows.length){try{[this.exampleUrl]=await this.$refs.coverCanvas.render({templateId:'letter',templateVersion:2,text:this.v(this.memorial?'memoryEmptyCopy':'bookEmptyCopy'),salutation:this.v(this.memorial?'startMemory':'start'),media:[],mode:this.memorial?'deceased':'current'},this.scope,this.petId,valid,{firstPageOnly:true,example:true});}catch(_){}return;}
   for(const row of (this.viewMode==='works'?this.visibleWorks:[])){if(!valid())return;try{const w=this.store.read().works[row.id];const d=w.snapshot;const [url]=await this.$refs.coverCanvas.render(w.templateVersion>=4?d.renderPayload:{seal:d.seal,templateId:w.templateId,templateVersion:w.templateVersion||1,text:d.text||d.original,media:d.media,petName:d.hidePetName?'':w.petName||this.petName,title:d.title,dateText:d.dateText||d.localDate,hideDate:d.hideDate,salutation:d.salutation,signature:d.signature,mode:d.mode},this.scope,this.petId,valid,{firstPageOnly:true});if(valid())this.covers={...this.covers,[row.id]:url};}catch(_){if(valid())this.coverErrors={...this.coverErrors,[row.id]:true};}}
   const targets=this.viewMode==='photos'?this.photoRows:this.visibleRecords.filter(r=>!hasCareContent(r)&&lifePhotos(r).length).map(row=>({key:row.id,asset:lifePhotos(row)[0]}));
   for(const item of targets){if(!valid())return;try{const p=await resolveNarrativePhoto(item.asset,this.scope,this.petId);if(valid())this.recordPhotos={...this.recordPhotos,[item.key]:p.path};else releaseNarrativePhoto(p.path);}catch(_){if(valid())this.coverErrors={...this.coverErrors,[item.key]:true};}}
  },
  tr(k){return t('narrative.'+k);},back(){if(getCurrentPages().length>1)uni.navigateBack();else uni.switchTab({url:'/pages/home/home'});},
  current(){return !this.recordReadError&&isDataScopeCurrent(this.scope)&&getActivePet()?.id===this.petId;},
  readFailed(){this.resetPhotoExport();this.recordReadError=true;this.clearCovers();this.rows=[];this.recipes=[];this.atlas=[];this.savedProposals=[];this.recall=null;this.metadataRow=null;this.comparison=[];this.cleanupPending=false;},
  load(){this.recordReadError=false;try{this.loadRecords();}catch(_){this.readFailed();}},
  loadRecords(){const key=JSON.stringify([captureDataScope(),getActivePet()?.id,narrativeMode(getActivePet()?.relationshipStage||getActivePet()?.status)]);if(this.contextKey!==key){this.resetPhotoExport();this.resetSearch();this.findOpen=false;this.searchOpen=false;this.toolsOpen=false;this.extras=false;this.scrollTarget='';this.comparison=[];this.metadataRow=null;this.viewMode='records';this.scrollTop=0;this.contextKey=key;}this.clearCovers();this.rows=[];this.atlas=[];this.recipes=[];this.savedProposals=[];this.petName='';this.petId='';this.store=null;this.scope=captureDataScope();if(!this.scope.ready)return;const pet=getActivePet();if(!pet)return;this.petId=pet.id;this.petName=pet.name;this.memorial=narrativeMode(pet.relationshipStage||pet.status)==='deceased';this.store=getNarrativeStore(pet.id,this.scope);this.cleanupPending=this.store.read().mediaGarbage.length>0;this.refresh();},
  async retryCleanup(){if(!this.current())return;try{await removeUnusedNarrativeMedia(this.store,[]);this.cleanupPending=false;this.message='';}catch(_){this.cleanupPending=true;this.message=this.tr('mediaCleanupFailed');}},
  refresh(){if(this.recordReadError)return;try{this.refreshRecords();}catch(_){this.readFailed();}},
  refreshRecords(){if(!this.current())return;if(!this.memorial)syncCollections(this.store,'current',{month:true});const state=this.store.read();this.rows=[...Object.values(state.drafts).filter(r=>r.mode===(this.memorial?'deceased':'current')&&(lifeText(r).trim()||hasCareContent(r)||r.media?.length)).map(r=>({...r,_deleteTarget:r,_group:'drafts'})),...Object.values(state.works).filter(w=>this.memorial||(w.snapshot?.renderPayload?.mode||w.snapshot?.mode||'current')==='current').map(w=>({...w.snapshot,...(w.templateVersion>=4?{title:w.snapshot.renderPayload.title,media:w.snapshot.renderPayload.media,original:w.snapshot.renderPayload.blocks.map(b=>b.text).join('\n')}:{}),_version:w.templateVersion,id:w.id,_savedAt:w.savedAt,_template:w.templateId,_deleteTarget:w,_group:'works'})),...this.store.list().filter(r=>this.memorial||r.mode==='current').map(r=>({...r,_deleteTarget:r}))];this.recipes=this.memorial?[]:collectionRecipes(this.store);this.atlas=lifeAtlas(this.store.list());this.savedProposals=COMPANION_PROPOSALS.filter(p=>(state.proposals.saved||[]).includes(p.id));this.proposalsClosed=state.proposals.closed;this.updateRecall();this.loadCovers();},
  openRecipe(recipe){if(!this.current()||!recipe.available)return;uni.navigateTo({url:'/pages/card-compose/card-compose?booklet='+encodeURIComponent(recipe.key)+'&petId='+encodeURIComponent(this.petId)});},
  openProposal(p){uni.navigateTo({url:`/pages/narrative/narrative?tag=${p.tag}&proposal=${p.id}`});},
  restoreProposals(){this.store.updateSection('proposals',{...this.store.read().proposals,closed:false});this.refresh();},
  edit(row){if(!this.current())return;if(row?._version>=4){uni.navigateTo({url:'/pages/card-compose/card-compose?work='+encodeURIComponent(row.id)});return;}if(!row&&!this.memorial){uni.navigateTo({url:'/pages/calendar/calendar'});return;}if(row?.dailyVersion===2){uni.navigateTo({url:'/pages/calendar/calendar?recordId='+encodeURIComponent(row.id)+'&petId='+encodeURIComponent(this.petId)});return;}if(row?.legacy){uni.navigateTo({url:'/pages/calendar/calendar?date='+encodeURIComponent(row.localDate)});return;}const query=row?(row._group==='works'?'work=':'id=')+encodeURIComponent(row.id):'';uni.navigateTo({url:'/pages/narrative/narrative?'+query});},
  toggle(row,key){if(!this.current())return;try{this.store.setMetadata(row.id,{[key]:!row[key]});this.refresh();}catch(_){this.message=this.tr('draftFailed');}},
  async remove(row){
   if(!this.visible)return;try{if(!this.current())return;}catch(_){this.readFailed();return;}
   const store=this.store,scope=this.scope,memorial=this.memorial,epoch=++this.removalEpoch;
   const valid=()=>{try{return this.visible&&this.current()&&scope===this.scope&&store===this.store&&memorial===this.memorial&&epoch===this.removalEpoch;}catch(_){return false;}};
   try{
    if(!row._deleteTarget)throw Object.assign(new Error('NARRATIVE_VERSION_CONFLICT'),{code:'NARRATIVE_VERSION_CONFLICT'});
    const plan=store.prepareRemoval(row.id,row._group==='works'?'works':row._group==='drafts'?'drafts':'record',row._deleteTarget);
    const result=await new Promise(resolve=>uni.showModal({title:this.tr('delete'),content:this.tr(row._group==='works'?'deleteWorkHint':'deleteSourceHint'),confirmText:this.tr('delete'),success:resolve,fail:()=>resolve({confirm:false})}));
    if(!result.confirm||!valid())return;
    let removeWorks=false;
    if(plan.kind!=='works'&&plan.linkedCount){const choice=await new Promise(resolve=>uni.showActionSheet({itemList:['一并删除 '+plan.linkedCount+' 件关联作品','保留独立作品，仅删除原记录','取消删除'],success:resolve,fail:()=>resolve({tapIndex:2})}));if(![0,1].includes(choice.tapIndex)||!valid())return;removeWorks=choice.tapIndex===0;}
    const state=store.read(),refs=[...narrativeMediaRefs(state),...(row.media||[]),...Object.values(state.dailyDrafts).flatMap(d=>d?.form?.media||[]),...Object.values(state.compositions).flatMap(d=>d?.payload?.media||[])];
    if(plan.kind==='works')store.removeWork(row.id,plan);else store.remove(row.id,removeWorks,plan);
    if(!valid())return;this.refresh();
    try{await removeUnusedNarrativeMedia(store,refs);}catch(_){if(valid()){this.cleanupPending=true;this.message=this.tr('mediaCleanupFailed');}}
   }catch(e){if(valid()){this.message=['NARRATIVE_VERSION_CONFLICT','NARRATIVE_SOURCE_MISSING'].includes(e.code)?'记录或关联作品已变化，请重新查看后再删除。':'删除未完成，原资料仍需确认，请重新读取后重试。';this.refresh();uni.showToast({title:this.message,icon:'none'});}}

  }
 }
};
</script>
